insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('mammoth-cave-kentucky', '12A', 'Mammoth Cave National Park', 'United States', 'The world''s longest known cave system', 'future', 'verified', 'mountainValley', 'Appalachia & the Smokies', '{"adventure","hiking","family","culture","parks"}', '{"adventurous","historic","family-friendly","rugged"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Historic Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["culture","adventure","family"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234640) or 877-444-6777; walk-up not guaranteed","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":1,"blurb":"\"This classic Mammoth Cave Tour visits many of the historic areas that originally made Mammoth Cave famous. Going through tunnels that humans have used for thousands of years\"; 2 hours, 2 miles, 540 stairs; adult $24, youth $18, child $6. \"there are no alternative routes.\""},{"name":"Domes and Dripstones Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["adventure","family","hiking"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234640) or 877-444-6777","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":2,"blurb":"\"This tour begins in a sinkhole, passes through huge domes, amazing breakdown, and ends in the dripstone section known as Frozen Niagara\"; 2 hours, 0.75 miles, 638 stairs; adult $30, youth $25, child $8."},{"name":"Frozen Niagara Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["family","senior","adventure"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234640) or 877-444-6777","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":3,"blurb":"\"The naturally decorated Frozen Niagara section remains one of the most famous at Mammoth Cave\"; \"ideal for anyone with difficulty walking long distances or negotiating stairs\"; 1.25 hours, 0.25 miles, 64 stairs; adult $26, youth $22, child $7."},{"name":"Accessible Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["senior","family","culture"],"booking_route":"Recreation.gov (recreation.gov/ticket/234640/ticket/94)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":4,"blurb":"\"Utilizing the Elevator Entrance, this tour emerges near the famous Snowball Room\" and continues through historic Cleaveland Avenue; 2 hours, 0.5 miles, no stairs, 12 tickets per tour time; adult $27, youth $21, child $7."},{"name":"Wild Cave Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov (recreation.gov/ticket/234640/ticket/96); minimum two participants","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":5,"blurb":"\"The most extreme tour offered at Mammoth Cave, this crawling tour is an all-day adventure underground\"; 6 hours, 5 miles, about 500 stairs, age 16+, chest and hip no more than 42 inches; coveralls, helmets, knee pads and head lamps \"are provided by the park\"; $79."},{"name":"Violet City Lantern Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["culture","adventure","hiking"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234640) or 877-444-6777","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":6,"blurb":"\"A truly historic way to experience Mammoth Cave, this tour travels exclusively by lantern light\"; 3 hours, 3 miles; \"the use of flashlights is prohibited\"; age 6+; adult $32, youth $27."},{"name":"Grand Avenue Tour","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov (recreation.gov/ticket/facility/234640) or 877-444-6777","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":7,"blurb":"\"At 4 hours long, this lengthy tour explores the geologic diversity of what Mammoth Cave has to offer. Going through slot canyons, tubular passageways, tall canyons, and tunnels sparkled with gypsum\"; age 6+; adult $42, youth $34."},{"name":"Heritage Trail to Sunset Point","source":"https://www.nps.gov/thingstodo/heritage-trail.htm","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"none needed - free park trail; entrance to the park is free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"A 0.6-mile out-and-back to \"a park-favorite panorama of the Green River Valley\"; \"The first .5 miles of the trail is a raised, wooden walkway\" with railings and benches; \"appropriate for all visitors and all ranges of mobility\"; free."},{"name":"Green River paddle, Dennison Ferry to Green River Ferry","source":"https://www.nps.gov/maca/planyourvisit/canoeing-kayaking-and-boating.htm","accessed":"2026-10-03","si":["adventure","wildlife","family"],"booking_route":"none needed with your own boat; rentals from the two NPS-listed liveries","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"7.6 miles, about 2.5 to 4 hours: \"scenic flat waters with gravel bars, islands, and back channels\"; \"Riverside caves are accessible by paddle craft at lower water levels\". The Green \"is home to more than 150 fish species, more than 70 species of mussel\". River use is prohibited at or above 20 feet on the park gauge."},{"name":"Green River Ferry","source":"https://www.nps.gov/places/green-river-ferry.htm","accessed":"2026-10-03","si":["family","culture"],"booking_route":"none needed - free; status on the ferry hotline","commission_status":"none","tier_absent_reason":"not-sold","wells":["move"],"draw_rank":10,"blurb":"\"first developed in 1934 and is the last remaining active river ferry in the park\"; shuttles vehicles, hikers and bikers \"364 days a year\"; free; vehicles up to 12 tons and no more than 16 feet long; hotline (270) 758-2166."},{"name":"Cedar Sink Trail","source":"https://www.nps.gov/thingstodo/cedar-sink-trail.htm","accessed":"2026-10-03","si":["hiking","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"an enormous sinkhole called Cedar Sink. It hosts a stunning variety of spring and summer wildflowers\"; a 1-mile loop of 45-60 minutes with \"A total of 295 stairs\"; about 10 minutes from the visitor center; free."},{"name":"Echo River Spring Trail","source":"https://www.nps.gov/places/green-river-ferry.htm","accessed":"2026-10-03","si":["hiking","senior","wildlife"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"From the Green River Ferry parking area: \"a one-mile wheelchair accessible loop path through the forest. This hike is a great destination for avid bird watchers\"; picnic tables at the trailhead, benches and viewpoints along the way."},{"name":"Mammoth Cave Railroad Bike and Hike Trail","source":"https://www.nps.gov/maca/planyourvisit/bicycling.htm","accessed":"2026-10-03","si":["hiking","family","culture"],"booking_route":"none needed - free trail; e-bike rental in Cave City","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"9 miles on the line of the railroad that \"brought early tourists to Mammoth Cave\" from 1886 until \"its final run on August 1, 1931\"; reached from Park City, points on Mammoth Cave Parkway and the visitor center; helmets recommended."},{"name":"North side backcountry trails","source":"https://www.nps.gov/maca/planyourvisit/backctrycamping.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed for day use; reached by the Green River Ferry or via Brownsville","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Mammoth Cave National Park''s backcountry boasts 37 square miles of forest and more than 60 miles of trails\"; open to hikers, horses and, on Big Hollow, mountain bikes - \"over 10 miles of single track\" from Maple Springs."},{"name":"The Lodge at Mammoth Cave","source":"https://mammothcavelodge.com/lodging-mammoth-cave/","accessed":"2026-10-03","si":["family","senior","culture"],"booking_route":"own website booking (Cloudbeds) or (844) 760-CAVE / 270-758-2225","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":15,"blurb":"\"located directly next to the visitor center\": Sunset Terrace rooms (2 queens, up to 5), Heritage Trail rooms, Historic Cottages (1-2 people, no TV or Wi-Fi), seasonal pet-friendly Woodland Cottages ($30 a night per pet) and Family Cabins \"Just opened in August 2025\" with full kitchens; 2811 Entrance Rd."},{"name":"Mammoth Cave Campground","source":"https://www.nps.gov/maca/planyourvisit/camping.htm","accessed":"2026-10-03","si":["family","group","hiking"],"booking_route":"Recreation.gov (recreation.gov/camping/gateways/2818) or 877-444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":16,"blurb":"\"Tent campsites, group campsites, RV campsites, and accessible campsites just a short walk from the visitor center\"; 111 sites, open March 1 - November 30, $25 a night ($12.50 Senior/Access), group $40; RVs up to 38 ft; no hookups."},{"name":"Houchin Ferry Campground","source":"https://www.nps.gov/maca/planyourvisit/fees.htm","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"Recreation.gov or 877-444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":17,"blurb":"\"Every campsite has a river view\"; 12 tent-only sites, open year round, $20 a night ($10 Senior/Access), \"No RV or Trailers\"; 15 miles from the visitor center and 1.5 miles from Brownsville."},{"name":"Maple Springs Group Campground","source":"https://www.nps.gov/maca/planyourvisit/camping.htm","accessed":"2026-10-03","si":["adventure","group","hiking"],"booking_route":"Recreation.gov or 877-444-6777","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":18,"blurb":"\"Group campsites, horseback group campsites, and RV campsites just a 10 minute drive from the visitor center\" across the Green River Ferry; 7 sites with hookups (no sewer), $50 a night, March 1 - November 30; sites 1-4 \"are designed to accommodate horses\"."},{"name":"Backcountry and riverside camping","source":"https://www.nps.gov/maca/planyourvisit/backctrycamping.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"Recreation.gov (recreation.gov/camping/campgrounds/10048983) or the campground kiosk","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"Thirteen designated backcountry sites \"accessible only by hiking or horseback\", one party of up to eight; riverside and island camping on the Green and Nolin \"only accessible by boat\"; $10 permit per trip; river levels must stay below 20 feet."},{"name":"Green River Grill & Bar","source":"https://mammothcavelodge.com/dining-mammoth-cave/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in; phone (270) 451-2288","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":20,"blurb":"In the Lodge: \"Kentucky favorites prepared with local and regional farm-fresh foods\", \"a 3-star certified Green Restaurant\"; open daily, lunch 11:00 am-3:30 pm, dinner 5:00-8:00 pm, kids menu; (270) 451-2288."},{"name":"The Lantern Café","source":"https://mammothcavelodge.com/dining-mammoth-cave/","accessed":"2026-10-03","si":["family","culinary"],"booking_route":"walk-in counter service","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":21,"blurb":"In the Lodge, across the foot bridge from the visitor center: \"grab and go food needs and ice cream\", 10:00 am-6:00 pm; also a 3-star certified Green Restaurant."},{"name":"Caver''s Camp Store","source":"https://www.nps.gov/maca/planyourvisit/goodsandservices.htm","accessed":"2026-10-03","si":["family","hiking"],"booking_route":"walk-in store","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","gear"],"draw_rank":22,"blurb":"On Mammoth Cave Parkway beside the campground: \"general supplies, snacks, groceries, souvenirs, quick food service as well as showers and a self-service laundry\"; the only legal firewood source, since \"transport of firewood into the park is prohibited\"; Sun-Thu 9-5, Fri-Sat 8-7."},{"name":"Ranger-led stargazing","source":"https://www.nps.gov/maca/planyourvisit/stargazing.htm","accessed":"2026-10-03","si":["family","wildlife"],"booking_route":"none needed - check the park calendar","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":23,"blurb":"\"Ranger-led stargazing programs are offered throughout the year to provide an opportunity to experience unfettered views of the starry night\"; attendees view planets \"through telescopes provided by the park\"; dates on the park calendar."},{"name":"Fishing the Green and Nolin rivers","source":"https://www.nps.gov/maca/planyourvisit/fishing.htm","accessed":"2026-10-03","si":["adventure","wildlife"],"booking_route":"none needed - no licence inside the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":24,"blurb":"\"No fishing license or permit is required within the boundary of Mammoth Cave National Park\"; Kentucky size and possession limits apply; the rivers hold \"muskellunge, bluegill, catfish, bass, perch, crappie, and other game fish\"."},{"name":"Mammoth Cave Historic Train","source":"https://www.nps.gov/places/maca-historic-train.htm","accessed":"2026-10-03","si":["culture","family","rail"],"booking_route":"none needed - free roadside exhibit","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":25,"blurb":"\"Hercules\" and Coach #2: a Baldwin \"dummy\" locomotive and combine coach \"among the last of their kind used in the United States\"; the 9-mile line from Glasgow Junction (Park City) opened \"November 8th of 1886\" and ran 45 years. National Register of Historic Places."},{"name":"Cave-tour kit: light jacket and sturdy shoes","source":"https://www.nps.gov/maca/planyourvisit/cave-tours.htm","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"affiliate referral to a gear retailer (REI.com via AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":26,"blurb":"The NPS kit list for every tour: \"Cave temperatures are cool, averaging around 54°F. It''s a good idea to bring a light jacket\"; \"Wear sturdy shoes and watch your step on the rugged pathways.\" Not allowed: \"Child backpack carriers\", strollers, tripods and large trekking backpacks."},{"name":"Crawling-tour boots: lace-up, ankle-high, slip-resistant","source":"https://www.nps.gov/maca/planyourvisit/explore-all-tours.htm","accessed":"2026-10-03","si":["adventure","hiking"],"booking_route":"affiliate referral to a gear retailer (REI.com via AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":27,"blurb":"For the Introduction to Caving and Wild Cave tours: \"Participants must provide their own lace-up hiking boots that cover the ankle and are equipped with slip-resistant tread. Athletic shoes or slick-soled footwear do not meet these requirements\" - \"no exceptions\"; bring a spare pair of shoes for boot cleaning."},{"name":"Tick kit: permethrin, gaiters, long sleeves","source":"https://www.nps.gov/maca/planyourvisit/safety.htm","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral (Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":4,"commission_basis":"published","wells":["gear"],"draw_rank":28,"blurb":"\"Ticks can be prevalent throughout the park\"; the NPS says wear \"light-colored clothing, long sleeves, and long pants, with pant legs tucked into socks\", \"Consider wearing gaiters\", and \"0.5% Permethrin insecticide applied to clothing is effective in reducing tick bites\"; picaridin \"will not ruin synthetic fabrics\"."},{"name":"US Coast Guard-approved life jacket","source":"https://www.nps.gov/maca/planyourvisit/canoeing-kayaking-and-boating.htm","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"affiliate referral to a gear retailer (REI.com via AvantLink); liveries supply boats","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":29,"blurb":"\"Always wear a life jacket\": PFDs are \"required to be worn by children ages 12 and under at all times while on rivers inside of Mammoth Cave National Parks\"; \"Federal and state law requires a Type I, II, or III PFD for each person onboard\"; tubes and pool rafts are prohibited on the rivers."},{"name":"Green River Canoeing and Kayaking","source":"https://greenrivercanoeing.com/","accessed":"2026-10-03","si":["adventure","family","wildlife"],"booking_route":"FareHarbor (own website)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":30,"blurb":"Listed by the NPS as a livery operating under a commercial use authorization; \"the oldest licensed outfitter in Mammoth Cave National Park\", founded by Joel and Barbara Davis with four canoes, now \"more than 100 canoes and kayaks\"; trips \"ranging from three hours to two nights or more\"; open April-October; 23839 Louisville Rd, Park City; (270) 773-5712."},{"name":"Adventures of Mammoth Cave","source":"https://adventuresofmammothcave.com/","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"Singenuity (book.singenuity.com) from the own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":31,"blurb":"Cave City; the NPS lists it as \"Mammoth Cave Canoe and Kayak\". \"the first and original Canopy-styled tour in the state\" - a five-line zipline canopy tour from $64, canoe and kayak rental from $65, mountain e-bike rental from $45 for the 9-mile railroad trail, horseback rides from $45 (ages 5+); (270) 773-6087."},{"name":"Double J Stables and Horsemen''s Campground","source":"http://www.doublejstables.com/","accessed":"2026-10-03","si":["adventure","family","hiking"],"booking_route":"phone 270-286-0310 (reservations required)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","stay"],"draw_rank":32,"blurb":"Named by the NPS as the authorized guided-riding operator; \"located off the Northeastern corner of Mammoth Cave National Park\" with direct trail access - \"You do not need to cross or ride on any public roads\"; small guided groups, riders \"as young as 6\"; campground with water/electric and rustic sites, \"We welcome campers without horses\"; reservations required, 270-286-0310."},{"name":"Cave Country RV Campground","source":"https://cavecountryrv.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Campspot (campspot.com/book/cave-country-rv-campground)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":3,"commission_pct_high":3,"commission_basis":"published","wells":["stay"],"draw_rank":33,"blurb":"216 Gaunce Drive, Cave City: \"All sites are pull-throughs & full-hookup with 50amp\"; pickleball courts, seasonal pool, laundry, fire pits, fitness centre, dog park and walking trail; check-in 1:00 pm Central; (270) 773-4678."},{"name":"Singing Hills RV Park and Campground","source":"https://singinghillsrvpark.com/","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"phone reservation, pay on arrival","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":34,"blurb":"\"open year round and is only two miles from Mammoth Cave National Park\"; owned since 2007 by Eldon and Beth Brown, who live on site; catch-and-release pond; \"word of mouth advertising has us full nearly every night during tourist season\"; reservations on the honor system by phone."},{"name":"Yogi Bear''s Jellystone Park Camp-Resort: Mammoth Cave","source":"https://www.hipcamp.com/en-US/d/united-states/kentucky/horse-cave/camping/glamping","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"Hipcamp listing (own site at sunoutdoors.com returned HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":35,"blurb":"Cave City, Barren County: 276 sites listed; \"a great selection of RV and tent camping sites or deluxe cabins\" with \"on-site activities with Yogi Bear and friends, swimming at Karst Beach, jumping pillows, and fishing ponds\"; celebrating its 35th anniversary season."},{"name":"Riverbend Retreat","source":"https://www.hipcamp.com/en-US/d/united-states/kentucky/horse-cave/camping/glamping","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":36,"blurb":"Horse Cave, Hart County: \"campsite and cabin rentals right on the banks of the Green River\", \"just 10 miles from Mammoth Cave National Park\", with an on-site boat ramp and fishing and swimming from the property."},{"name":"Horse Cave KOA Holiday","source":"https://koa.com/campgrounds/horse-cave/","accessed":"2026-10-03","si":["glamping","family","motoring"],"booking_route":"koa.com own booking or phone","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":37,"blurb":"KOA Ave, Horse Cave: \"Camping Cabins, Wagons, Teepees, Treehouses and shady Pull-Thru RV Sites, a swimming pool, mini golf, a jumping pillow, free fishing\"; Deluxe Cabins with full baths; reserve 1-270-786-2819."},{"name":"Noble Pine Campground","source":"https://www.hipcamp.com/en-US/d/united-states/kentucky/horse-cave/camping/glamping","accessed":"2026-10-03","si":["glamping","family"],"booking_route":"Hipcamp (listing /en-US/land/kentucky-noble-pine-campground-2ejhzln8)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":38,"blurb":"On \"the north side of Mammoth Cave National Park\" (Edmonson County): \"1 glamping bell tent, 1 glamping aframe\", a 3-bedroom ''Trailboss'' cabin and 10 RV/tent sites with water and 30-amp; hot showers; horses, goats and chickens on the farm."},{"name":"Mollys Ridge Glamping and Camping","source":"https://www.hipcamp.com/en-US/d/united-states/kentucky/horse-cave/camping/glamping","accessed":"2026-10-03","si":["glamping","hiking"],"booking_route":"Hipcamp (listing /en-US/land/kentucky-mollys-ridge-glamping-and-camping-nelhjooz)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":39,"blurb":"Horse Cave, Hart County: \"an off-the-grid adventure featuring Glamping and Camping rentals located directly over Mammoth Cave in the largest growing Amish community in Kentucky\"; 36 acres of trails."},{"name":"Hampton Inn Cave City","source":"https://hotelguides.com/kentucky/mammoth-cave-national-park-ky-hotels.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":40,"blurb":"Listed by HotelGuides at \"803 Sanders Street, I-65, Exit 53, Cave City\", \"8 miles from Mammoth Cave National Park\". Hilton''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Holiday Inn Express & Suites Horse Cave","source":"https://hotelguides.com/kentucky/mammoth-cave-national-park-ky-hotels.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_hi