insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('isle-royale-michigan', '12A', 'Isle Royale National Park', 'United States', 'Lake Superior wilderness archipelago of wolves and moose', 'future', 'verified', 'mountainValley', 'The Great Lakes', '{"hiking","wildlife","adventure","diveglobal","parks"}', '{"remote","wild","rugged","serene"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Wolves and moose of Isle Royale","source":"https://www.nps.gov/isro/learn/nature/wolves.htm","accessed":"2026-10-03","si":["wildlife","hiking","expedition"],"booking_route":"none needed - wildlife seen on the park''s trails and shores","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"\"The gray wolf (Canis lupus)... has been the prevailing predator of Isle Royale National Park since its arrival to the island in the late 1940s\", most likely \"by crossing an ice bridge that formed between the island and the Canadian mainland during the winter of 1948\"; the population has ranged \"from 50 animals in 1980 to a low of two animals between 2016 and 2018\". Best chance of a sighting: \"along lakeshores, open areas, or hiking trails.\""},{"name":"Backcountry campgrounds and permits","source":"https://www.nps.gov/isro/planyourvisit/camping.htm","accessed":"2026-10-03","si":["hiking","group","adventure","expedition"],"booking_route":"free self-issued permit on arrival (small parties); group permits reserved ahead with the park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"36 campgrounds located across the island\", reached by foot or watercraft, each with tent sites, a water source and outhouses; \"Permits are required, regardless of group size or method of travel, for all overnight stays.\" Parties of six or fewer camp free on a first-come, first-served permit; groups of seven or more reserve ahead at \"$25 per permit fee\". Fires \"only... in designated metal rings or standing grills.\""},{"name":"Rock Harbor Lodge","source":"https://www.nps.gov/isro/planyourvisit/rock-harbor-lodge.htm","accessed":"2026-10-03","si":["wildlife","senior","family","romance"],"booking_route":"rockharborlodge.com online booking or (877) 841-1064; bookable 366 days ahead","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":3,"blurb":"\"The only full-service lodging facility on the island\", on the northeast end: \"Sixty rooms are available; each accommodates four persons and offers a private bath. Each room provides a Lake Superior view\", plus \"Twenty duplex cottages\" with kitchenettes. Operated by \"a park concessionaire, Isle Royale Resorts\"; the lodge site is \"© Aramark 2026\". 2026 season \"June 5, 2026 – September 12, 2026\"."},{"name":"165 miles of island trails","source":"https://www.nps.gov/isro/planyourvisit/first-timer-s-guide.htm","accessed":"2026-10-03","si":["hiking","adventure","wildlife"],"booking_route":"none needed - park entrance fee only","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"There are 165 miles of trails and 36 campgrounds\" on an island \"approximately 50 miles long and 9 miles wide\", topped by \"Mount Desor at 1,394 feet\". Day hikes start from both Rock Harbor and Windigo; the NPS warns \"Terrain is rough and uneven\" and lists day-pack essentials: water, snacks, rain gear, first aid kit, map and compass."},{"name":"NPS backpacking kit list for Isle Royale","source":"https://www.nps.gov/isro/planyourvisit/packing-guide.htm","accessed":"2026-10-03","si":["hiking","adventure","expedition"],"booking_route":"bought before the crossing - REI.com via AvantLink, or gear hire from Arrive Outdoors","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":5,"blurb":"The NPS''s own \"Essential Equipment\" list: \"Well broken-in boots\", \"Waterproof backpacking tent\", \"Sleeping bag (rated to 20 degrees F)\", \"Raingear (breatheable)\", \"Water filter (0.4 microns or smaller)\", \"Backpacking stove\", \"Topographic map\", \"Sunscreen\", \"Insect repellant\", \"Headnet\", \"Compass\". Clothing: wool and quick-drying synthetics \"ideal for Isle Royale''s changeable climate\". Pack weight: \"no more than 30% of your body weight\"."},{"name":"Water filter and treatment kit","source":"https://www.nps.gov/isro/planyourvisit/drinking-water.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"bought before the crossing - REI.com via AvantLink, or Amazon Associates (Outdoors)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":6,"blurb":"\"All surface lake and stream water should be considered contaminated with pathogens (non-potable)\"; \"Potable water is only available in Rock Harbor and Windigo.\" The NPS methods: a virus-rated purifier, or a \"Water Filter (0.4 microns or finer) + Chemical Treatment\", or boiling \"at least one minute (bring plenty of fuel canisters)\". UV purifiers \"have not been manufacturer-tested for hydatid tapeworm... and cannot be considered effective.\" Bring \"a replacement cartridge\"."},{"name":"Animal-resistant hard-sided food container","source":"https://www.nps.gov/isro/planyourvisit/food-storage.htm","accessed":"2026-10-03","si":["hiking","wildlife","adventure"],"booking_route":"bought before the crossing - REI.com via AvantLink, or Amazon Associates (Outdoors)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":7,"blurb":"\"In recent years, a small number of wolves have taken an interest in human food and activities.\" Backpackers store food, trash and scented items in campground lockers \"OR... in approved, animal-resistant hard-sided containers\"; \"Do not hang food in campgrounds\"; kayak hatches \"are not animal resistant\"; off-trail campers stash containers \"200 feet away from campsite\". The packing guide lists an \"Animal Resistent Container\"."},{"name":"Rain gear and warm layers for the crossing","source":"https://www.nps.gov/isro/planyourvisit/day-trips.htm","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"bought before the crossing - Amazon Associates (Apparel) or REI.com via AvantLink","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":8,"blurb":"The NPS day-trip orientation: \"Isle Royale''s weather can be unpredictable. Pack your bag with the elements in mind, including rain gear and warm layers for the Lake Superior crossing.\" Day-trippers should be ready for an unexpected overnight: \"bringing essential items: prescriptions, food, and extra clothing for variable weather. Consider bringing a tent, sleeping pads, and sleeping bags; Isle Royale does not provide these items for visitors.\""},{"name":"Interior-lake canoe and kayak routes","source":"https://www.nps.gov/isro/planyourvisit/canoe-and-kayak.htm","accessed":"2026-10-03","si":["adventure","wildlife","expedition"],"booking_route":"none needed for the routes - a backcountry permit to overnight; rentals in person at Rock Harbor or Windigo","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"Lake Superior is well-known for its cold waters, fog, and sudden, wave-generating squalls. Small, open vessels are encouraged to use interior lake waterways instead.\" Interior routes and portages lie on the northeast half, marked \"P\" on a post; canoes \"at least 15'' long\"; \"Recreational kayaks are not recommended.\" Boat rentals at Windigo and Rock Harbor; ferries carry canoes and kayaks for a fee."},{"name":"Isle Royale shipwrecks by dive permit","source":"https://www.nps.gov/isro/planyourvisit/scuba-diving.htm","accessed":"2026-10-03","si":["diveglobal","adventure","culture"],"booking_route":"free dive registration at the Rock Harbor, Windigo or Houghton visitor center","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Isle Royale''s ten major shipwrecks span seventy years\", \"from wooden side-paddle steamers to massive steel freighters.\" Surface water \"rarely exceeds 55 degrees Fahrenheit; below 50 feet, 34-37 degrees. Full wetsuit is necessary; a drysuit is recommended.\" Every diver registers at a visitor center; \"There are no facilities for filling dive cylinders at Isle Royale.\""},{"name":"MV Sandy sightseeing tours from Rock Harbor","source":"https://www.rockharborlodge.com/things-to-do/sightseeing-tours/","accessed":"2026-10-03","si":["culture","wildlife","family","senior"],"booking_route":"rockharborlodge.com Book Now, reservable in advance","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":11,"blurb":"\"Sightseeing tours are offered six days a week\": Passage Island (\"a picturesque 1881 lighthouse\"), Hidden Lake/Lookout Louise (\"where you can see Ontario''s Sleeping Giant\"), Edisen Fishery/Rock Harbor Lighthouse (\"the oldest lighthouse (1855) on Isle Royale\") and a Raspberry Island sunset cruise. Adult $60, children 11 and under $30; open to all visitors."},{"name":"Rock Harbor fishing charters","source":"https://www.rockharborlodge.com/marina/fishing-charters/","accessed":"2026-10-03","si":["adventure","culinary","family"],"booking_route":"rockharborlodge.com Book Now","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":12,"blurb":"\"Half-day fishing charters for up to four guests\" aboard \"an inspected 24'' charter boat operated by a U.S.C.G licensed captain\", June 5 - September 11, 2026; a Michigan DNR licence is sold at the Lodge Office. \"Catch and Cook\": \"the Lighthouse Restaurant can cook your catch for you once you return\"."},{"name":"Washington Harbor Camper Cabins (Windigo)","source":"https://www.rockharborlodge.com/lodging/washington-harbor-camper-cabins/","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"rockharborlodge.com or (877) 841-1064","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":13,"blurb":"On the southwest end: \"a unique alternative to tent camping\"; each cabin has \"2 Twin Bunk Beds and 1 Full-size Futon\", table and chairs, outdoor grill and private deck; \"All cabins do not have indoor plumbing, but guests have access to shared outdoor restroom facilities.\" The NPS counts \"two rustic, one-room camper cabins\" with electrical outlets."},{"name":"Rock Harbor Dockside Store and Windigo store","source":"https://www.nps.gov/isro/planyourvisit/rock-harbor-lodge.htm","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"walk-in on the island","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","shop"],"draw_rank":14,"blurb":"The NPS: the Rock Harbor store \"offers groceries, freeze dried foods, daily fishing licenses (cash only), fishing tackle, stove fuel, camping, hiking, and boating accessories, showers, laundry facilities\"; the Washington Harbor (Windigo) store sells \"camping supplies, stove fuel\" and rents motorboats, canoes and kayaks. Fuel cannot fly: Isle Royale Seaplanes says iso-butane and white gas \"can be purchased on Isle Royale, at both Windigo and Rock Harbor.\""},{"name":"Houghton Visitor Center and RANGER III","source":"https://www.nps.gov/isro/planyourvisit/ranger-iii-info.htm","accessed":"2026-10-03","si":["adventure","family","senior"],"booking_route":"RANGER III reservations through the NPS (fares page renders by script; not read)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":15,"blurb":"The NPS''s own 165-foot, 648-ton passenger vessel: \"All service departs from Houghton, Michigan and travels to either Rock Harbor or Windigo\"; it \"generally travels to Isle Royale Tuesdays and Fridays and returns Wednesdays and Saturdays\", about 6 hours, departing 9:00 am ET. The Houghton Visitor Center, 800 E. Lakeshore Drive, is open May 26 - September 20 Monday-Friday 8 am - 5 pm ET and Saturday 10 am - 5 pm ET."},{"name":"Isle Royale Queen IV (Copper Harbor)","source":"https://isleroyale.com/","accessed":"2026-10-03","si":["adventure","family","senior"],"booking_route":"own website reservations or (906) 289-4437","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":16,"blurb":"From 14 Waterfront Landing, Copper Harbor: \"voyage from beautiful Copper Harbor to the wilderness of Isle Royale in only 3 hours\". The NPS: departs 8:00 am EDT, leaves Rock Harbor 2:45 pm EDT, same-day return for day-trippers and overnighters, typically early May to end of September; \"There is no car ferry service.\" (906) 289-4437."},{"name":"Grand Portage Isle Royale Transportation Lines (Voyageur II, Sea Hunter III)","source":"https://www.isleroyaleboats.com/rates.html","accessed":"2026-10-03","si":["adventure","hiking","family"],"booking_route":"own website Book Now (2027 opens late November, per the operator)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["move"],"draw_rank":17,"blurb":"From Grand Portage, MN: Sea Hunter III to Windigo, \"$110.50 Adult Camper One-way fare\", \"$120.50 Day trip passenger over and back in the same day\"; Voyageur II circles the island to Windigo, McCargoe Cove, Belle Isle and Rock Harbor ($110.50 adult one way from Grand Portage); canoes/kayaks $55.25 one way. Terminal parking \"$5\" a day, charged by the village of Grand Portage."},{"name":"Isle Royale Seaplanes (Hubbell)","source":"https://www.isleroyaleseaplanes.com/","accessed":"2026-10-03","si":["adventure","senior","romance"],"booking_route":"own website request form or 1-906-483-4991","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["fly"],"draw_rank":18,"blurb":"The park''s \"sole concessionaire offering seaplane transportation\", from 26998 W. 16th Street, Hubbell, MI, to Windigo or Rock Harbor: one way \"$289/per person\", round trip or day trip \"$420/per person\", \"These ticket prices include all taxes and fees\"; flight about 45 minutes; parking $10 a day. No stove fuel of any kind on board."},{"name":"Keweenaw Adventure Company","source":"https://www.keweenawadventure.com/","accessed":"2026-10-03","si":["adventure","expedition","family"],"booking_route":"own website","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":19,"blurb":"Copper Harbor, \"Established in 1994\": guided Lake Superior sea kayak day trips and \"multi-day Lake Superior kayak tours on Isle Royale National Park\", mountain-bike shuttles and repair, \"a small retail shop where we supply essential bike parts and kayak accessories\", and \"Canoe, sit-on-top kayak and SUP rentals\"."},{"name":"Portage Paddle Sports","source":"https://portagepaddlesports.com/","accessed":"2026-10-03","si":["family","adventure"],"booking_route":"walk-up rentals (no booking method on the page)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["gear","activities"],"draw_rank":20,"blurb":"At 1100 W Lakeshore Dr, Houghton (the City RV Park entrance) and 2000 Jasberg Street, Hancock: \"Renting Paddle Boards and Kayaks and serving up hand dipped Ice Cream\"; the City of Houghton adds \"From Memorial Day to Labor Day they offer bike, kayak, and paddle board rentals\". Both sites read \"Closed for the season\" on 2026-10-03."},{"name":"Isle Royale and Keweenaw Parks Association store","source":"https://irkpa.org/","accessed":"2026-10-03","si":["hiking","culture"],"booking_route":"own online store","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["shop","gear"],"draw_rank":21,"blurb":"The park''s nonprofit partner at 800 E. Lakeshore Dr., Houghton: \"Books, Maps, Apparel & Souvenirs\" - \"your purchases support our parks\" - and an annual \"Isle Royale Night Sky Photography Workshop\" on the island for beginner and intermediate photographers."},{"name":"Hampton Inn & Suites Houghton","source":"https://www.mtu.edu/admissions/visit/lodging/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"hilton.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":22,"blurb":"Listed by Michigan Technological University among Houghton hotels at \"820 Shelden Avenue, Houghton, MI 49931\", 906-487-1700 - the same street as the NPS Houghton Visitor Center. Hilton''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"Holiday Inn Express Houghton-Keweenaw","source":"https://www.mtu.edu/admissions/visit/lodging/","accessed":"2026-10-03","si":["family","senior"],"booking_route":"ihg.com (brand booking; not fetched - HTTP 403)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":10,"commission_pct_high":10,"commission_basis":"benchmark","wells":["stay"],"draw_rank":23,"blurb":"Listed by Michigan Technological University among Houghton hotels at \"1110 Century Way, Houghton, MI 49931\", 906-482-1066. IHG''s own page refused the fetch (HTTP 403), so nothing else about the property is stated here."},{"name":"The Vault Hotel","source":"https://thevaulthotel.com/","accessed":"2026-10-03","si":["romance","culture"],"booking_route":"own website booking","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"600 Shelden Ave, Houghton: \"Housed inside a beautifully restored historic bank\" - \"Formerly the Houghton National Bank, Built 1887\" - with a guest-only cocktail bar, The Counting Room; the hotel cites \"Conde Nast Reader''s Choice Awards Top 15 Hotels in Midwest 2023 & 2024.\""},{"name":"Keweenaw Mountain Lodge","source":"https://keweenawmountainlodge.com/","accessed":"2026-10-03","si":["romance","golf","culture","family"],"booking_route":"own website or phone; no walk-ins","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"Copper Harbor: \"A four-season historic wilderness resort at the top of the Keweenaw, est. in 1934\", a WPA-era lodge and \"international dark sky park\"; \"24 cabins, with 27 units\" lined along the first hole of the golf course and the forest. \"Lodging reservations are done in advance, either online or over the phone — no walk-ins.\""},{"name":"Grand Portage Lodge & Casino","source":"https://grandportage.com/index.php/staying/hotel-rooms-suites","accessed":"2026-10-03","si":["family","entertainment"],"booking_route":"own website or phone","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"The Minnesota gateway: renovated rooms with queen or king beds, \"access to our indoor heated pool, hot tub, and fitness room\", suites with fireplace and whirlpool; free cancellation \"until noon the day of check-in\". The Grand Portage ferry line names it as a place to stay overnight before the crossing."},{"name":"City of Houghton RV Park","source":"https://www.cityofhoughton.com/rv-park","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"telephone only, 906-482-8745","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"1100 West Lakeshore Drive on the Portage Waterway: \"25 sites\" with water, sewer and \"20-30-50 amp electric service\"; \"We do not accept pop-up campers or tents as there are no bathroom/shower facilities\". Daily rate $60, one week $55 a night, one month+ $50 a night; next to the Ray Kestner Waterfront Park beach and a four-mile waterfront trail into downtown. Opens \"May 1, 2026 (weather dependent)\"."},{"name":"Grand Portage Marina RV Park and Campground","source":"https://grandportage.com/index.php/staying/the-rv-park","accessed":"2026-10-03","si":["motoring","family","hiking"],"booking_route":"phone 1-218-475-2476","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"\"Located adjacent to the Marina with 29 sites with full hook ups and a comfort station with restrooms, showers and laundry facilities. There may be a few tent sites available.\" Season \"lasts until October 15th\"; 1-218-475-2476. The ferry line names it for \"RV sites and tent sites\" in Grand Portage."},{"name":"Fort Wilkins Historic State Park campground","source":"https://copperharbor.org/portfolio/fort-wilkins-state-park-campground/","accessed":"2026-10-03","si":["culture","family","motoring","hiking"],"booking_route":"Michigan DNR state park reservations (michigan.gov refused the fetch - HTTP 403)","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":29,"blurb":"About a mile east of Copper Harbor: \"camping, day-use facilities, a restored 1844 military outpost and one of the first lighthouses on Lake Superior\", with costumed interpreters and a rentable cabin on Lake Fanny Hooe (Copper Harbor Improvement Association). Hipcamp lists the campground at \"160 sites · Tents, RVs\" with electrical hookups and toilets."},{"name":"Keweenaw Waters Resort","source":"https://www.keweenawwatersresort.com/","accessed":"2026-10-03","si":["glamping","family","motoring"],"booking_route":"own website booking or 906-231-9193","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":30,"blurb":"17800 Canal Road, Houghton, on the Keweenaw Waterway: a \"Single level glamping cabin with 1 bedroom, 1 bath, and 1 queen bed plus a two-twin loft\" and water-view patio, Northwoods cabins up to 3,700 sq. ft., and \"89 Full-Hookup 20, 30, and 50 amp sites\"; \"RV Park & Campground Sites Starting at $34/Night\", \"Cabins Starting at $95/Night\"; electric boat rentals on the Portage Canal."},{"name":"Greenstone Grill (Rock Harbor)","source":"https://www.rockharborlodge.com/dining/greenstone-grill/","accessed":"2026-10-03","si":["culinary","hiking","family"],"booking_route":"walk-in on the island","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":31,"blurb":"\"Pizza, burgers, sandwiches, fresh salads, late-night snacks, cappuccino, and a wide selection of regional beer and wine each evening\", plus grab-and-go; the deck \"is a favorite gathering spot\". June 5 - September 12, 2026; breakfast 6:30-11:00 am, lunch/dinner 11:00 am - 8:00 pm."},{"name":"Lighthouse Restaurant (Rock Harbor)","source":"https://www.rockharborlodge.com/dining/lighthouse-restaurant/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"on the island (no booking method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":32,"blurb":"The lodge dining room, June 5 - September 12, 2026: breakfast 7:00-8:30 am, dinner 5:30-8:00 pm. The NPS: \"hearty meals, including fresh lake trout\"; through \"Catch and Cook\" it will cook a charter guest''s catch."},{"name":"Harbor Haus","source":"https://www.harborhaus.com/","accessed":"2026-10-03","si":["culinary","romance"],"booking_route":"dinner reservations by phone","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":33,"blurb":"Copper Harbor, \"situated right on the shore of Lake Superior\": \"a vast dining menu featuring fresh local fish, seafood, steaks\", with local berries and vegetables in season and \"No prefabricated dishes\"; ore freighters pass the picture windows. The site notes \"the Harbor Haus is for sale\". Dinner reservations by phone."},{"name":"Keweenaw Brewing Company taproom","source":"https://www.kbc.beer/","accessed":"2026-10-03","si":["culinary","culture"],"booking_route":"walk-in","commission_status":"none","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":34,"blurb":"Downtown Houghton on the north side of Shelden Ave. (US-41): \"a daily selection of fresh beers brewed right on our premises\" with sacks of roasted peanuts; \"$4.25 pints\"; local restaurants deliver to the door."},{"name":"The Library Restaurant and Brewpub","source":"https://thelibraryhoughton.com/","accessed":"2026-10-03","si":["culinary"],"booking_route":"walk-in (no booking method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":35,"blurb":"62 Isle Royale St., Houghton, Monday-Saturday 11 a.m. - 12 a.m., under new owners: beer production is paused while \"new federal and state liquor licenses\" process, with a Michigan tap takeover meanwhile."},{"name":"Island View Dining Room (Grand Portage)","source":"https://grandportage.com/index.php/dining/island-view","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"walk-in (no booking method on the page)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":36,"blurb":"At Grand Portage Lodge: \"delicious comfort food with a spectacular view of Lake Superior and Pete''s Island\", breakfast, lunch and dinner seven days a week; breakfast 7-11 am, dinner to 9 or 10 pm; a Friday steak buffet at $19.99."},{"name":"Grand Portage National Monument","source":"https://www.nps.gov/grpo/index.htm","accessed":"2026-10-03","si":["culture","hiking","family"],"booking_route":"none needed - visitor site; free backcountry permits online","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":37,"blurb":"In Grand Portage, MN: \"the first National Park Service unit to be co-managed with a Tribal Nation\" - a Heritage Center on the fur trade and Anishinaabe culture and a reconstructed fur trade depot; summer hours 5/23 - 10/12, Heritage Center 9 am - 5 pm daily; two backcountry campsites at Fort Charlotte by free permit."}],"faq":[{"q":"Can you drive to Isle Royale National Park?","a":"No. \"Isle Royale can only be accessed by crossing Lake Superior via a boat or seaplane\" and \"No Vehicles are Allowed on the Island\" - the ferries carry people and select freight only. Your vehicle stays on the mainland in Houghton, Copper Harbor, Hubbell or Grand Portage.","source":"https://www.nps.gov/isro/planyourvisit/first-timer-s-guide.htm","accessed":"2026-10-03"},{"q":"How do you get to Isle Royale National Park from Grand Portage?","a":"By ferry. The Sea Hunter III runs Grand Portage to Windigo in \"1.5 hours\", departing \"9:30 am eastern time/8:30 am central time\"; the Voyageur II reaches Windigo in \"2 hours\" and continues to Rock Harbor. Both are seasonal.","source":"https://www.nps.gov/isro/planyourvisit/directions.htm","accessed":"2026-10-03"},{"q":"How much is the ferry to Isle Royale National Park?","a":"From Grand Portage, Grand Portage Isle Royale Transportation Lines publishes \"$110.50 Adult Camper One-way fare\" to Windigo on the Sea Hunter III, \"$120.50 Day trip passenger over and back in the same day\", and $110.50 adult one way on the Voyageur II; canoes and kayaks are $55.25 one way. Other ferries publish their own fares.","source":"https://www.isleroyaleboats.com/rates.html","accessed":"2026-10-03"},{"q":"Can you fly to Isle Royale National Park?","a":"Yes, by seaplane. \"Isle Royale Seaplanes is the sole concessionaire offering seaplane transportation to Isle Royale National Park\", flying from Hubbell, Michigan to Windigo and Rock Harbor, typically \"from mid-May through mid-September\". The nearest airport, Houghton County Memorial, is 8 miles from Houghton.","source":"https://www.nps.gov/isro/planyourvisit/isle-royale-seaplanes.htm","accessed":"2026-10-03"},{"q":"What are the Isle Royale National Park fees?","a":"\"Isle Royale National Park charges a $7 per person daily entrance fee to enter or remain within the park per calendar day\"; children 15 and under are exempt. An Isle Royale Season Pass costs $60 and covers the holder and up to three adults. The park takes credit cards only for entrance fees.","source":"https://www.nps.gov/isro/planyourvisit/fees.htm","accessed":"2026-10-03"},{"q":"Can you camp at Isle Royale National Park?","a":"Yes. There are \"36 campgrounds located across the island\". \"Permits are required, regardless of group size or method of travel, for all overnight stays\"; parties of six or fewer get free first-come, first-served permits, and groups of seven or more reserve ahead at $25 per permit.","source":"https://www.nps.gov/isro/planyourvisit/camping.htm","accessed":"2026-10-03"},{"q":"When does Isle Royale National Park close for the season?","a":"\"Isle Royale National Park is open every year from April 16 through October 31. The island is closed from November 1 through April 15 due to extreme winter weather conditions\"; the closure \"extends 4.5 miles out into Lake Superior from the island.\"","source":"https://www.nps.gov/isro/planyourvisit/hours.htm","accessed":"2026-10-03"},{"q":"Is Isle Royale National Park dog friendly?","a":"No: \"Dogs, cats and other mammals are not allowed on the island.\" \"Service dogs are welcome on Isle Royale. However, a service dog permit must be obtained prior to your trip.\"","source":"https://www.nps.gov/isro/faqs.htm","accessed":"2026-10-03"},{"q":"What time zone is Isle Royale National Park in?","a":"\"Isle Royale National Park is on eastern time, since it is part of Keweenaw County, Michigan.\" The Grand Portage boats run on central time.","source":"https://www.nps.gov/isro/faqs.htm","accessed":"2026-10-03"},{"q":"How big is Isle Royale National Park?","a":"\"The main island, Isle Royale, is approximately 50 miles long and 9 miles wide.\" The park is an archipelago of \"over 400 islands\", with \"165 miles of trails and 36 campgrounds\"; the high point is Mount Desor at 1,394 feet.","source":"https://www.nps.gov/isro/planyourvisit/first-timer-s-guide.htm","accessed":"2026-10-03"}],"seo":{"meta_title":"Isle Royale National Park: Ferries, Camping & Wolves | TravelWell","meta_description":"Boat or seaplane only: five crossings from Michigan and Minnesota, 36 campgrounds, Rock Harbor Lodge, wolves and moose, and the NPS backpacking kit list.","slug":"isle-royale-national-park-michigan","primary_keyword":"Isle Royale National Park","jsonld_type":"TouristDestination"},"hero":{"query":"Isle Royale National Park Rock Harbor"}}'::jsonb, 53),
  ('illinois-beach-illinois', '12A', 'Illinois Beach State Park', 'United States', 'Lake Michigan dunes, beach ridges and campground', 'future', 'verified', 'mountainValley', 'The Great Lakes', '{"family","hiking","wildlife","adventure","parks"}', '{"coastal","serene","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Lake Michigan swimming beaches","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"none needed - IDNR states beaches charge \"$1 a day per person for beach use only\" (dnr.illinois.gov/parks/camp/faqcamping.html)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"6.5 miles of sandy Lake Michigan shore across the North and South units: \"Swimming is a major summertime attraction along the sandy shorelines, and both units provide ample parking.\" \"There are no on-duty lifeguards, so please be careful.\" Dogs are not allowed on the beach."},{"name":"The dunes and beach ridge shoreline","source":"https://dnr.illinois.gov/parks/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["wildlife","hiking","senior"],"booking_route":"none needed - open park land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"The only remaining beach ridge shoreline left in the state, with dunes and swales, sprawling marshes, forests of oak\"; \"More than 650 species of plants have been recorded in the dunes area alone\"; \"Prickly pear cactus thrives in large colonies in the dry areas\"; the sandy ridges \"are crowned by black oak forests with an open, savanna-like appearance.\""},{"name":"Illinois Beach Nature Preserve","source":"https://dnr.illinois.gov/parks/about/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["wildlife","hiking","culture"],"booking_route":"none needed - open park land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":3,"blurb":"\"In 1964 the area south of Beach Road was dedicated as the first Illinois Nature Preserve\"; the Illinois Dunes Preservation Society was established in 1950 \"to protect the natural qualities of the area.\" \"Dogs are not allowed on the beach or in the nature preserve.\""},{"name":"Illinois Beach State Park Campground","source":"https://dnr.illinois.gov/parks/camp/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","motoring","adventure"],"booking_route":"ExploreMoreIL (recreation.exploremoreil.com), up to 180 days ahead; unreserved sites first-come, first-served","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":4,"blurb":"\"220 Class A Premium sites with electricity and access to showers and sanitary facilities\"; open \"April 1 through Nov. 15\"; \"Campsites do not have individual water or sewer hookups, but there are water hydrants throughout the campground and a dump station at the front of the campground\"; \"No Possession or Consumption of Alcohol allowed on any site in the Campground.\" IDNR''s statewide schedule lists Class A Premium at $25 ($15 camping + $10 utility)."},{"name":"Illinois Beach Hotel","source":"https://dnr.illinois.gov/parks/lodge/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","romance","senior"],"booking_route":"own website illinoisbeachhotel.com (blocked our fetch - Cloudflare) or Booking.com; 224-259-2600","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established","commission_pct_low":4,"commission_pct_high":4,"commission_basis":"published","wells":["stay"],"draw_rank":5,"blurb":"The park''s resort, \"Located directly on the shores of Lake Michigan\": IDNR calls it \"the only hotel in the state that is nestled along the sandy beaches of Lake Michigan\", with room types \"many of which offer sweeping views of Lake Michigan or the natural beauty of Illinois Beach State Park\"; \"Open year round\". Booking.com: \"a 2-minute walk from Illinois Beach State Park\"."},{"name":"Sun and heat kit the park says to bring","source":"https://dnr.illinois.gov/parks/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","hiking","senior"],"booking_route":"affiliate referral to gear retail (REI.com via AvantLink; Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear","shop"],"draw_rank":6,"blurb":"The park''s own beach-safety list: \"Drink plenty of fluids.\" \"Wear sunglasses that absorb at least 90 percent of UV sunlight.\" \"Wear sunscreen (SPF 30 or higher) and a wide-brimmed hat.\" \"Spend part of your day in shaded areas.\" The kit need: sunscreen SPF 30+, a wide-brimmed hat, UV-blocking sunglasses, water bottles and shade. No product or price is named here."},{"name":"Campsite water and power kit for a no-hookup site","source":"https://dnr.illinois.gov/parks/camp/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"affiliate referral to gear retail (REI.com via AvantLink; Dometic via AvantLink)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":5,"commission_pct_high":6,"commission_basis":"published","wells":["gear","shop"],"draw_rank":7,"blurb":"The campground''s own terms set the kit: sites have electricity but \"Campsites do not have individual water or sewer hookups, but there are water hydrants throughout the campground and a dump station at the front of the campground.\" The kit need: carrying and storing water from the hydrants, and RV dump-station gear. No product or price is named here."},{"name":"South Unit trails","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["hiking","wildlife","family"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":8,"blurb":"\"The southern part of the park features 5 miles of trails, including a 2.2-mile loop trail with a graveled surface.\" Dogs on leash are allowed on trails outside the nature preserve."},{"name":"Camp Logan Trail","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["hiking","culture","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":9,"blurb":"\"In the north, Camp Logan Trail is a 1.8-mile multi-use loop.\" The park''s naturalist walks note the park \"transformed from a military base into the park we know and love today.\""},{"name":"Zion Bike Trail","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["adventure","family"],"booking_route":"none needed - free public trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":10,"blurb":"\"Bikers can travel between the North and South units of Illinois Beach State Park by utilizing the Zion Bike Trail, a section of trail connecting 29th Street at the south end to 17th Street at the north end.\""},{"name":"Dead River","source":"https://dnr.illinois.gov/parks/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["wildlife","hiking"],"booking_route":"none needed - open park land","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":11,"blurb":"\"For much of the year, a stream known as Dead River is blocked by sandbars formed by waves at the mouth of the river, creating a sluggish, marshy habitat.\""},{"name":"IBSP Nature Center","source":"https://dnr.illinois.gov/parks/interpret/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","wildlife","senior"],"booking_route":"none needed - free; park office (847) 662-4811","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":12,"blurb":"\"Interactive displays tell the story of both the people-focused and natural history of the IBSP, and games and species I.D. resources are sure to liven up your adventures in the park\"; an overlook deck and back patio; a Conservation Educator on hand; \"open Thursday through Monday from 9 a.m. to 4:30 p.m.\""},{"name":"Walks With a Naturalist","source":"https://dnr.illinois.gov/parks/event/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["wildlife","hiking","family","senior"],"booking_route":"none needed - meet at the Nature Center (no booking stated on the page)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"A weekly guided nature walk at Illinois Beach State Park, led by Nature Center staff. These relaxed, beginner-friendly walks will explore the park''s diverse habitats, including dunes, wetlands, forests, and shoreline.\" \"Every Saturday in April, May and June\", 10:30am-12:00pm; meet at the Nature Center; \"All ages welcome!\""},{"name":"Fishing and the Sand Pond pier","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["adventure","family","senior"],"booking_route":"none needed in the park (Illinois fishing licence rules not read in this build)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"Fishing is allowed along the beach area in both units (except in the swimming areas) and there are several small inland fishing ponds, including Sand Pond, where a disabled fishing pier is available.\""},{"name":"Picnic grounds of both units","source":"https://dnr.illinois.gov/parks/picnic/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","group","senior"],"booking_route":"none needed; groups of 25-60 by permit from the park office (847) 662-4811","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"\"Easy access to Lake Michigan makes Illinois Beach State Park a relaxing and enjoyable place to picnic with the family. Both the northern and southern units of the park contain ample picnic grounds, complete with tables.\" \"Groups of 25 - 60 must have a picnic permit.\" \"Alcohol is prohibited at Illinois Beach State Park.\""},{"name":"Nolan''s Restaurant","source":"https://dnr.illinois.gov/parks/lodge/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["culinary","family","romance"],"booking_route":"via the hotel, 224-259-2600 (reservation method not read - hotel site blocked our fetch)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":16,"blurb":"The Illinois Beach Hotel''s restaurant: IDNR says \"the hotel is known for locally sourced comfort food\" and offers \"an excellent dining option at its new restaurant, Nolan''s\"; Nolan''s \"Wednesday - Sunday 4:00 pm - 8:00 pm\"; bar Sunday-Thursday 11:00 am - 10:00 pm, Friday-Saturday to 11:00 pm."},{"name":"The Pavilion camp store and concession","source":"https://dnr.illinois.gov/parks/lodge/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["family","motoring"],"booking_route":"walk-in at the main parking lot","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat","shop","gear"],"draw_rank":17,"blurb":"\"Brand new in 2021 the Pavilion is located in the main parking lot and is a combination souvenir shop, camp store and concession stand. Guests can buy everything from firewood to t-shirts while enjoying a hot dog or soft serve ice-cream.\" IDNR''s concessions list names firewood and ice sales through the Illinois Beach Hotel, 224-259-2600."},{"name":"North Point Marina","source":"https://dnr.illinois.gov/parks/activity/park.adelinejaygeo-karisillinoisbeach.html","accessed":"2026-10-03","si":["sailing","adventure","yacht"],"booking_route":"slips and services through the marina (own website not located - northpointmarina.net is a different marina in Maryland)","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":18,"blurb":"IDNR: \"Located next to Illinois Beach, this full-service marina has 1,500 slips, a boat service center and food concession.\""},{"name":"Fish Lake Beach Camping Resort","source":"https://www.hipcamp.com/en-US/land/illinois-fish-lake-beach-camping-resort-1-5x5hno18","accessed":"2026-10-03","si":["motoring","family"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":19,"blurb":"Volo, Illinois: \"54 sites - RV, Tent, Lodging - 50 acres\" - 38 RV-only sites, 8 tent-only and 8 cabins; \"Full hookup sites\"; \"heated outdoor pool, hot tub, dog park, indoor pickleball court\" and lake access with \"beach, the boat rentals, the fishing\"; \"Family-friendly RV park... tucked into the heart of Lake County just 45 minutes north of Chicago\"; season \"May 1st through October 15th\"."},{"name":"Rehm Acres - Self Service","source":"https://www.hipcamp.com/en-US/land/illinois-rehm-acres-self-service-kk9hwyym","accessed":"2026-10-03","si":["motoring"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":20,"blurb":"Antioch, Illinois: RV-only vehicle sites, \"Vehicles under 19 feet allowed\" (travel trailers, pop-ups, class B RVs, campervans); \"Electrical hookup available\" under 30 amps; no toilet, potable water or showers; \"Great overnight spot to park between Chicago and Milwaukee only 2 miles off of 294...low-cost option to park and relax.\""},{"name":"Chain O''Lakes State Park campground","source":"https://www.hipcamp.com/en-US/state-park/united-states/illinois/chain-o-lakes/all","accessed":"2026-10-03","si":["family","adventure","motoring"],"booking_route":"ExploreMoreIL state reservations (as with all Illinois state parks); listed on Hipcamp","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay","activities"],"draw_rank":21,"blurb":"Hipcamp: \"Made up of nine lakes, this park is a water lover''s paradise. You can rent a kayak, canoe, or paddleboard to explore the shorelines\"; over 300 campsites with electricity, plus 33 primitive campsites and cabins; boat launches, a nature center, hiking and equestrian trails and a camp store."},{"name":"Indigo Zen Garden","source":"https://www.hipcamp.com/en-US/land/wisconsin-indigo-zen-garden-kk9hmzx5","accessed":"2026-10-03","si":["glamping","family","romance"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":22,"blurb":"Caledonia, Wisconsin: a glamping dome with a bell tent and a children''s play tent, \"6 guests max - 3 bedrooms - 5 beds - 1 toilet\"; a stargazing dome, butterfly and fairy gardens, fire pit and outdoor shower; no potable water; \"Named one of the best Hipcamps to visit in 2026\"; 100% from 44 reviews."},{"name":"Glamp Chicago Yurt Urban Campsite","source":"https://www.hipcamp.com/en-US/land/illinois-glamp-chicago-yurt-urban-campsite-mxvhyxrx","accessed":"2026-10-03","si":["glamping","culture"],"booking_route":"Hipcamp","commission_status":"unknown","commission":"affiliate","tier_absent_reason"