insert into public.destinations (id, region_code, name, country, line, status, depth, img, sub_region, si, feel, tier_range, price_band, draw_rank, data, position) values
  ('starved-rock-illinois', '12A', 'Starved Rock State Park', 'United States', 'Eighteen sandstone canyons and rain-fed waterfalls', 'future', 'verified', 'mountainValley', 'The Great Lakes', '{"hiking","wildlife","family","glamping","culture","parks"}', '{"dramatic","rugged","historic","family-friendly"}', '{}', null, null, '{"safety":{"posture":"book-freely","source":"https://www.gov.uk/foreign-travel-advice/usa","verified":"2026-10-08"},"jewels":[{"name":"Starved Rock overlook","source":"https://dnr.illinois.gov/parks/about/park.starvedrock.html","accessed":"2026-10-03","si":["hiking","culture","wildlife","family"],"booking_route":"none needed - free; \"all state parks are free for everyone to enjoy\"","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":1,"blurb":"The \"125-foot sandstone butte\" the park is named for (the IDNR activity page lists the walk as \".6 miles Roundtrip\"); in the winter of 1682-83 \"the French constructed Fort St. Louis on top of Starved Rock due to its advantageous position overlooking the Illinois River.\" One of the best January eagle-viewing points."},{"name":"Canyon waterfalls and icefalls","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["hiking","family","adventure"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":2,"blurb":"\"There are 8 canyon waterfalls that are accessible to visitors: French, Wildcat, La Salle, Ottawa, Kaskaskia, Illinois, St. Louis, and Aurora.\" They \"occur March through June but, may dry out late June through October\"; in January the same canyons hold icefalls. \"Wading and swimming or using the canyons as waterslides are prohibited\" - fines start at $195."},{"name":"Starved Rock Lodge","source":"https://www.starvedrocklodge.com/","accessed":"2026-10-03","si":["culture","family","romance","senior","hiking"],"booking_route":"own website booking or 815-667-4211 / 800-868-7625","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":3,"blurb":"Built by the Civilian Conservation Corps from 1933 and opened in 1939; \"added to the National Register of Historic Places in May of 1985\"; its Great Hall fireplace is \"the largest in Illinois\". 69 guest rooms plus cabins, an indoor pool with two saunas and a hot tub; \"the only lodging facility in beautiful Starved Rock State Park.\" Open year-round; 815-667-4211."},{"name":"Wildcat Canyon","source":"https://dnr.illinois.gov/parks/activity/park.starvedrock.html","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":4,"blurb":"\"Wildcat Canyon 2 miles Roundtrip\" - one of the IDNR''s suggested hikes and one of the eight canyon waterfalls; the Lodge''s French Canyon trailhead \"leads to the eastern section of the park such as the overlooks, Wildcat Canyon, and La Salle Canyon.\""},{"name":"French Canyon","source":"https://dnr.illinois.gov/parks/activity/park.starvedrock.html","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":5,"blurb":"\"French Canyon .8 miles Roundtrip\" - the shortest canyon walk the IDNR suggests, reached from behind the visitor center; in winter it is \"not suitable... for those without micro cleats or Yaktrax\"."},{"name":"St. Louis and Aurora Canyons","source":"https://dnr.illinois.gov/parks/activity/park.starvedrock.html","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"none needed - free park trail","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":6,"blurb":"\"Aurora Canyon and St. Louis Canyon 3 miles Roundtrip\"; St. Louis Canyon is spring fed - \"The only icefall that formed this year because the canyon is spring fed is St. Louis Canyon.\" Trailhead from the St. Louis Canyon lot off Route 178."},{"name":"Winter bald eagle viewing","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["wildlife","family","senior"],"booking_route":"none needed - free","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":7,"blurb":"\"Bald eagles can be seen throughout the year fishing along the Illinois River\"; in January the best viewing is \"from the sandstone butte known as Starved Rock, the sea wall along the Illinois River across from the visitor center, or the Illinois Waterway Visitor Center\". The visitor center screens \"On the Wings of the Wind (bald eagle film) 15 minutes\"."},{"name":"Starved Rock State Park Campground","source":"https://dnr.illinois.gov/parks/camp/park.starvedrock.html","accessed":"2026-10-03","si":["family","hiking","motoring","group"],"booking_route":"ExploreMoreIL (recreation.exploremoreil.com), online only; accessible and youth-group sites by phone 815-667-4726","commission_status":"unknown","commission":"venue","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":8,"blurb":"\"133 Class-A Premium campsites. Electric hook-up only\" (30 or 50 amp); two shower houses with flush toilets, dump station, playground; maximum \"1 family... or 4 adults per site with 2 tents or 1 RV and 1 tent.\" \"RESERVATIONS ARE REQUIRED\", 6 months to 4 days ahead, online only; the West Loop is open all year, the East Loop closes from the weekend before Thanksgiving to April 1."},{"name":"Starved Rock Lodge log cabins","source":"https://www.starvedrocklodge.com/lodging/lodging/cabins/","accessed":"2026-10-03","si":["romance","culture","family"],"booking_route":"own website booking or 815-667-4211","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":9,"blurb":"\"These authentic log cabins were built in the 1930s by the Civilian Conservation Corps\": Sunset Cabins (quad cabins, some with a wood-burning fireplace) and three standalone Pioneer Cabins \"150 yards from the Lodge\" with no TVs, where dogs are allowed with a rabies certificate."},{"name":"Starved Rock Lodge Historic Trolley Tours","source":"https://www.starvedrocklodge.com/activities/activities/trolley-tours/","accessed":"2026-10-03","si":["culture","family","senior"],"booking_route":"own website (\"Online bookings subject to additional fees and taxes\") or (815) 220-7386","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","move"],"draw_rank":10,"blurb":"\"a 90-minute trolley tour with stops at the Starved Rock State Park Visitors Center, the IL Waterway Visitor Center and through downtown Utica\", April-December, Mon/Wed/Fri at 3 PM; Adults $20, Seniors $17, Children 12 and under $15. Seasonal Fall Color, Ghost and Hegeler Carus Mansion trolley tours."},{"name":"Sainte Genevieve riverboat cruises","source":"https://www.starvedrocklodge.com/activities/activities/water-cruises/","accessed":"2026-10-03","si":["family","romance","senior","culture"],"booking_route":"own website, (815) 220-7386 or the Lodge front desk","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":11,"blurb":"Booked through the Lodge: a Starved Rock Trolley to the boat, then a Sunset Cruise on the Illinois River (June-August $50 adults, $40 children; September-October with dinner $75/$65) or \"Lock and Lunch\" through the Starved Rock Lock ($77/$67; 2027 dates \"coming soon\")."},{"name":"Starved Rock Lodge guided seasonal hikes","source":"https://www.starvedrocklodge.com/activities/activities/guided-hikes/","accessed":"2026-10-03","si":["hiking","family","senior"],"booking_route":"own website or 815-220-7386","commission_status":"unknown","commission":"guide","tier_absent_reason":"does-not-compete","wells":["activities"],"draw_rank":12,"blurb":"\"Year-round, Saturday & Sunday at 10am, $25/person\", lunch included (a wrap, chips, granola bar, fruit and bottled water); special Mega Hikes \"four times a year\"; the Lodge has also launched its \"first-ever guided hiking tours at Matthiessen State Park\"."},{"name":"Starved Rock Visitor Center","source":"https://dnr.illinois.gov/parks/visitorcenter/park.starvedrock.html","accessed":"2026-10-03","si":["family","culture","senior"],"booking_route":"none needed - free; PO Box 509, Utica, IL 61373, 815-667-4726","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":13,"blurb":"\"should be the first stop\": museum-quality exhibits on history, geology and ecology; open \"Daily 9 a.m. to 4 p.m.\" (closed on listed holidays); films on request including the CCC and the bald eagle; the Le Rocher Gift Shop is run by the Starved Rock Foundation."},{"name":"Free IDNR naturalist programmes and Junior Ranger","source":"https://dnr.illinois.gov/parks/event/park.starvedrock.html","accessed":"2026-10-03","si":["family","wildlife","culture"],"booking_route":"free; some via Starved Rock Eventbrite registration","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":14,"blurb":"\"All IDNR/state park programs and events are free to park visitors\" - e.g. 10/17/26 \"Leaf Peeping and Tree Seeking\" hike and 12/13 nature journaling; Junior Ranger booklets at the visitor center earn \"their very own Junior Ranger badge\"."},{"name":"Illinois, Ottawa and Kaskaskia Canyons","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["hiking","senior","family"],"booking_route":"none needed - free park trails","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":15,"blurb":"On the park''s eastern edge off Route 71: \"Illinois, Ottawa, and Kaskaskia Canyons trails do not contain staircases but there are a few creek crossings where feet may get muddy or wet in the winter and spring\"."},{"name":"Starved Rock Lodge Restaurant","source":"https://www.starvedrocklodge.com/dining/dining/lodge-restaurant/","accessed":"2026-10-03","si":["culinary","family"],"booking_route":"online reservations on the Lodge site or (815) 220-7321","commission_status":"unknown","commission":"venue","tier_absent_reason":"does-not-compete","wells":["eat"],"draw_rank":16,"blurb":"\"open daily for breakfast, lunch and dinner. Reservations are recommended\"; Sunday brunch buffet 10:30 AM-3 PM; the Back Door Lounge and Veranda; the IDNR describes \"a restaurant, bar and grill with outdoor seating, cafe, and concession stand\". (815) 220-7321."},{"name":"Winter traction for icy canyon trails","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["hiking","adventure"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":17,"blurb":"The IDNR''s own kit advice: in winter \"Trails will be icy and snow packed. Traction devices such as micro cleats or Yaktrax on hiking boots are highly recommended.\" French and La Salle canyons are \"not suitable in winter for those without micro cleats or Yaktrax\"."},{"name":"Waterproof hiking shoes for spring mud","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":4,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":18,"blurb":"The IDNR on spring: \"Trails will be very muddy with standing water in a few areas. Waterproof hiking shoes are highly recommended, and a change of dry socks and clean shoes for the ride home. Please do not wash your shoes off in the park''s sinks.\""},{"name":"Water for hikers and dogs in summer","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["hiking","family"],"booking_route":"affiliate referral to a gear retailer (REI via AvantLink, or Amazon Associates)","commission_status":"commissioned","commission":"affiliate","tier_absent_reason":"does-not-compete","commission_pct_low":3,"commission_pct_high":5,"commission_basis":"published","wells":["gear"],"draw_rank":19,"blurb":"\"Visitors are asked to pack plenty of water for themselves and their pets in order to stay hydrated and cool on the trails\"; \"there are no bathrooms, trash cans, or water fountains located on the trail system\", and dogs must not \"drink from canyon waterfalls, creeks, or the Illinois River.\""},{"name":"Matthiessen State Park","source":"https://dnr.illinois.gov/parks/about/park.matthiessen.html","accessed":"2026-10-03","si":["hiking","adventure","family"],"booking_route":"none needed - free state park","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":20,"blurb":"The sister park: \"the park has grown to 1,938 acres\"; \"The Upper Dell begins at Deer Park Lake and continues to Cascade Falls, where the canyon drops 45 feet and the Lower Dell begins\"; the canyon runs \"approximately 1 mile\" to the Vermilion River. Its Vermilion River Area has the biking trails Starved Rock does not allow, \"just 2 miles south of the park\" (IDNR Q&A)."},{"name":"Illinois Waterway Visitor Center","source":"https://dnr.illinois.gov/content/dam/soi/en/web/dnr/parks/documents/starvedrock-common-park-qa.pdf","accessed":"2026-10-03","si":["wildlife","family","river"],"booking_route":"none needed (hours not read)","commission_status":"none","tier_absent_reason":"not-sold","wells":["activities"],"draw_rank":21,"blurb":"\"located just across from the park off of Dee Bennett Road\" - named by the IDNR as one of the three best January bald-eagle viewing points, and a stop on the Lodge''s Historic Trolley Tour."},{"name":"Kayak Starved Rock","source":"https://kayakstarvedrock.com/","accessed":"2026-10-03","si":["adventure","family","river"],"booking_route":"own website online booking (kayakstarvedrock.com/online-booking/)","commission_status":"unknown","commission":"operator","tier_absent_reason":"does-not-compete","wells":["activities","gear"],"draw_rank":22,"blurb":"\"#1 Starved Rock Kayaking Near Chicago since 2010\", 1170 N. 27th Road, Ottawa, directly across the river from the park: rents Perception touring and tandem kayaks \"with paddles and life jackets\" and runs 2-hour guided tours on weekends and holidays; the IDNR names it as the park''s kayak concession (\"Kayak and canoe rental is not available at the park\"). 630-567-4653."},{"name":"Camp Aramoni","source":"https://camparamoni.com/","accessed":"2026-10-03","si":["glamping","romance","culinary"],"booking_route":"ThinkReservations (secure.thinkreservations.com/camparamoni) from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":23,"blurb":"Tonica: \"a boutique campground and event venue\" on \"96 acres of lush forests on a former 19th century brickyard\" - \"Choose from 11 safari-style tents\"; the county tourism board adds that \"Breakfast, dinner and s''mores are included in your reservation price\". Its 1870 Bricks & Stones building hosts weddings and retreats."},{"name":"Starved Rock Family Campground","source":"https://starvedrockfamilycampground.com/","accessed":"2026-10-03","si":["motoring","family","glamping"],"booking_route":"phone (815) 202-2088 or the own site''s Ways to Stay page (booking engine not identified)","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":24,"blurb":"757 N 3029th Rd, Utica: \"a family-friendly RV park near Starved Rock\", \"Less than 7 miles to Starved Rock State Park\"; \"RV, Tent, or Glamping\"; seasonal outdoor pool, playground, dog park, laundry, shower house (closed in winter), camp store and Wi-Fi. (815) 202-2088."},{"name":"Pleasant Creek Campground","source":"https://www.pleasantcreekcampground.com/","accessed":"2026-10-03","si":["family","motoring","hiking"],"booking_route":"ResNexus booking engine from the own site","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":25,"blurb":"926 N. 2150th Road, Oglesby, \"just 5 minutes or 5 miles South of Starved Rock State Park\" on 50+ wooded acres along a Vermilion River tributary: \"over 120 campsites\" for trailers, RVs and tents plus \"7 furnished cabins\", a spring-fed stocked fishing pond, bathhouse and general store. 815-431-0936."},{"name":"Starved Rock Treehouses","source":"https://www.starvedrocktreehouses.com/","accessed":"2026-10-03","si":["romance","glamping","hiking","family"],"booking_route":"own website availability page","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":26,"blurb":"1208 IL-71, Ottawa: \"Four handcrafted luxury treehouses on 26 private acres, each sleeping eight, with a footbridge to the park''s trails right at your doorstep\"; \"Summer weekdays from $750/night\"; watercraft rental offered; cites \"Best of the Midwest 2026 - Midwest Living\"."},{"name":"Kishauwau Cabins","source":"https://kishauwaucabins.com/","accessed":"2026-10-03","si":["romance","family","wildlife"],"booking_route":"own website","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":27,"blurb":"Tonica: \"Cabin Rentals 10 Minutes from Starved Rock State Park\" - 17 cabins with fully stocked kitchens, wood stove or gas fireplace, personal fire pit and grill; \"WiFi is not offered in our cabins and cell service is very spotty\"; an optional bed and breakfast package."},{"name":"Grand Bear Resort at Starved Rock","source":"https://www.grandbearresort.com/","accessed":"2026-10-03","si":["family"],"booking_route":"own website or reservations@grandbearresort.com","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":28,"blurb":"2643 Route 178, North Utica: suites, cabins and villas with \"Waterpark Wristbands & Pool Towels\" included; \"STARVED ROCK''S ONE AND ONLY Indoor Waterpark Resort\" (currently on an off-season Thu-Sun waterpark schedule). 1 (866) 399-3866."},{"name":"Harbor Inn at Heritage Harbor","source":"https://www.visitheritageharborinn.com/","accessed":"2026-10-03","si":["family","river","romance"],"booking_route":"own website","commission_status":"unknown","commission":"hotel","tier_absent_reason":"not-established","wells":["stay"],"draw_rank":29,"blurb":"1851 Old Chicago Rd, Ottawa: vacation rentals on the Illinois River from villas to \"Bunkies\" and a Canopy Collection; the county tourism board notes \"on-property bike and boat rentals\" and Harbor House by Valentino''s."},{"name":"Fairfield Inn & Suites by Marriott Peru","source":"https://hotelguides.com/attraction-maps/illinois/map-hotels-near-starved-rock-state-park-il.html","accessed":"2026-10-03","si":["family","senior"],"booking_route":"marriott.com (brand booking; not fetched - HTTP 403)","commission_status":"commissioned","commission":"hotel","tier_absent_reason":"not-established"